'use client'

/**
 * RelayReportReader — hand-written (not generated by the converter).
 * The dashboard's "report" page: a Relay Research report from
 * config/reports.json (public or private) in the shared report layout.
 * Mounted by the Dashboard shell via scripts/dc-port/patches.mjs.
 */

import ReportArticle, { type ReportLabels } from '@/components/relay-app/ReportArticle'
import { getReportEntry, reportView } from '@/lib/reports'

const LABELS: ReportLabels = {
  back: 'Reports',
  takeaways: 'Key takeaways',
  keyMetrics: 'Key metrics',
  keyFindings: 'Key findings',
  whyThisMatters: 'Why this matters:',
  background: 'Why we built this',
  marketContext: 'Market context',
  providerLandscape: 'Provider landscape',
  implications: 'What this means for you',
  methodology: 'Data sources & methodology',
  sources: 'Sources',
  published: 'Published',
  lastUpdated: 'Last updated',
  minRead: 'min read',
  related: 'Related reports',
  copyLink: 'Copy link',
  copied: 'Link copied',
  downloadPdf: 'Download PDF',
}

type Props = { slug?: string; onNavigate?: (key: string, params?: Record<string, unknown>) => void; onOpenReport?: (slug: string) => void }

export default function RelayReportReader({ slug, onNavigate, onOpenReport }: Props) {
  const entry = slug ? getReportEntry(slug, 'app') : undefined
  const back = () => onNavigate?.('intelligence', { tab: 'reports' })
  if (!entry) {
    return (
      <div className="sc-host" data-sc-name="Relay Report Reader" style={{ padding: '56px 40px', textAlign: 'center', color: '#8a8f98', fontSize: '14px' }}>
        This report isn’t available.{' '}
        <span role="link" tabIndex={0} onClick={back} style={{ color: '#f7f8f8', cursor: 'pointer' }}>
          Back to Reports
        </span>
      </div>
    )
  }
  return (
    <div className="sc-host" data-sc-name="Relay Report Reader">
      <ReportArticle {...reportView(entry, 'app', 'en')} labels={LABELS} variant="app" onBack={back} onOpenRelated={onOpenReport} />
    </div>
  )
}
